window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5db3b544aa71cd0b"]={"versions": [{"id": "FIG-5db3b544aa71cd0b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung des beispielhaften Hochlaufs (Startup) und der Controller-Zustandsübergänge im AUTOSAR TTCAN Interface (<code>AUTOSAR_SWS_TTCANInterface</code>). Das Diagramm veranschaulicht die zeitliche Abfolge der Initialisierungs- und Synchronisationsphasen in Relation zu den Controller-Modi des CAN Interfaces (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Controller-Zustände (CanIf Controller States)</strong>:</li>\n<li><code>CANIF_CS_UNINIT</code>: Initialer, uninitialisierter Zustand.</li>\n<li><code>CANIF_CS_STOPPED</code>: Zustand nach Abschluss der Basisinitialisierung; Controller ist gestoppt, aber betriebsbereit.</li>\n<li><code>CANIF_CS_STARTED</code>: Vollständiger Betriebsmodus nach erfolgreicher Synchronisation.</li>\n<li><strong>Prozessphasen / Ereignisse</strong>:</li>\n<li><code>Initialisation</code>: Phase der Initialisierung des TTCAN-Controllers.</li>\n<li><code>Synchronisation according to ISO11898-4 [11]</code>: Zeitspanne zur Synchronisation des Controllers mit dem TTCAN-Kommunikationszyklus gemäß ISO 11898-4.</li>\n<li>Trigger-/Ereignispfeile für Initialisierungsstart, Abschluss der Initialisierung (<code>finished</code>), Anforderung/Trigger für <code>STARTED</code> sowie Zustandswechsel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das System beginnt im Zustand <code>CANIF_CS_UNINIT</code>. Ein eingehendes Signal stößt die Phase <code>Initialisation</code> an.</li>\n<li>Mit dem Abschluss der Initialisierung (<code>finished</code>) wechselt der Controllerzustand von <code>CANIF_CS_UNINIT</code> zu <code>CANIF_CS_STOPPED</code>.</li>\n<li>Im Zustand <code>CANIF_CS_STOPPED</code> wird die Phase <code>Synchronisation according to ISO11898-4 [11]</code> durch einen Trigger eingeleitet.</li>\n<li>Nach erfolgreichem Durchlauf der Synchronisationsphase wechselt der Controllerzustand an der rechten Intervallgrenze in <code>CANIF_CS_STARTED</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verdeutlicht das normative Zusammenspiel zwischen den CanIf-Zuständen und den Hardware-/Protokollphasen des TTCAN-Controllers.</li>\n<li>Der Wechsel in den Zustand <code>CANIF_CS_STARTED</code> darf erst nach erfolgreicher Synchronisation gemäß ISO 11898-4 erfolgen; während der Synchronisation verbleibt der Controller im Zustand <code>CANIF_CS_STOPPED</code>.</li>\n<li>Die Literaturreferenz <code>[11]</code> verweist innerhalb des Dokuments auf den Standard ISO 11898-4.</li>\n</ul>"}, {"id": "FIG-1fdc16716093d778", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung des beispielhaften Hochlaufs (Startup) und der Controller-Zustandsübergänge im AUTOSAR TTCAN Interface (<code>AUTOSAR_SWS_TTCANInterface</code>). Das Diagramm veranschaulicht die zeitliche Abfolge der Initialisierungs- und Synchronisationsphasen in Relation zu den Controller-Modi des CAN Interfaces (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Controller-Zustände (CanIf Controller States)</strong>:</li>\n<li><code>CANIF_CS_UNINIT</code>: Initialer, uninitialisierter Zustand.</li>\n<li><code>CANIF_CS_STOPPED</code>: Zustand nach Abschluss der Basisinitialisierung; Controller ist gestoppt, aber betriebsbereit.</li>\n<li><code>CANIF_CS_STARTED</code>: Vollständiger Betriebsmodus nach erfolgreicher Synchronisation.</li>\n<li><strong>Prozessphasen / Ereignisse</strong>:</li>\n<li><code>Initialisation</code>: Phase der Initialisierung des TTCAN-Controllers.</li>\n<li><code>Synchronisation according to ISO11898-4 [12]</code>: Zeitspanne zur Synchronisation des Controllers mit dem TTCAN-Kommunikationszyklus gemäß ISO 11898-4.</li>\n<li>Trigger-/Ereignispfeile für Initialisierungsstart, Abschluss der Initialisierung (<code>finished</code>), Anforderung/Trigger für <code>STARTED</code> sowie Zustandswechsel.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das System beginnt im Zustand <code>CANIF_CS_UNINIT</code>. Ein eingehendes Signal stößt die Phase <code>Initialisation</code> an.</li>\n<li>Mit dem Abschluss der Initialisierung (<code>finished</code>) wechselt der Controllerzustand von <code>CANIF_CS_UNINIT</code> zu <code>CANIF_CS_STOPPED</code>.</li>\n<li>Im Zustand <code>CANIF_CS_STOPPED</code> wird die Phase <code>Synchronisation according to ISO11898-4 [12]</code> durch einen Trigger eingeleitet.</li>\n<li>Nach erfolgreichem Durchlauf der Synchronisationsphase wechselt der Controllerzustand an der rechten Intervallgrenze in <code>CANIF_CS_STARTED</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verdeutlicht das normative Zusammenspiel zwischen den CanIf-Zuständen und den Hardware-/Protokollphasen des TTCAN-Controllers.</li>\n<li>Der Wechsel in den Zustand <code>CANIF_CS_STARTED</code> darf erst nach erfolgreicher Synchronisation gemäß ISO 11898-4 erfolgen; während der Synchronisation verbleibt der Controller im Zustand <code>CANIF_CS_STOPPED</code>.</li>\n<li>Die Literaturreferenz <code>[12]</code> verweist innerhalb des Dokuments auf den Standard ISO 11898-4.</li>\n</ul>"}], "trans": [{"from": "FIG-5db3b544aa71cd0b", "to": "FIG-1fdc16716093d778", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textkasten für die Synchronisationsphase: Quellenverweis von <code>ISO11898-4 [11]</code> auf <code>ISO11898-4 [12]</code> aktualisiert.</li>\n</ul>"}]};
